    public function testAnalyzesFilesWithTheirAssignedPolicyLimits(): void
    {
        $dir = sys_get_temp_dir() . '/locguard-policy-analyzer-' . uniqid('', true);
        mkdir($dir . '/src', 0755, true);
        $source = <<<'PHP'
<?php

function long_function(): void
{
    echo 'one';
    echo 'two';
}
