use PHPStan\Analyser\Scope;
use PHPStan\Rules\IdentifierRuleError;
use PHPStan\Rules\Rule;
use PHPStan\Rules\RuleErrorBuilder;
use Toolkit\PhpStan\Rule\Shared\TestMethodDetector;
use Toolkit\PhpStan\Rule\TestClass\OverrideMethodDetector;
use Toolkit\PhpStan\Support\TestClassScope;

/**
 * @implements Rule<\PhpParser\Node\Stmt\ClassMethod>
 */
final class NoHelperMethodInTestClassRule implements Rule
{
    /** @readonly */
    private TestMethodDetector $testMethodDetector;

    /** @readonly */
    private OverrideMethodDetector $overrideMethodDetector;

    /**
     * @param TestClassScope $testClassScope test class scope detector
     */
    public function __construct(
        /** @readonly */
        private TestClassScope $testClassScope,
        ?TestMethodDetector $testMethodDetector = null,
        ?OverrideMethodDetector $overrideMethodDetector = null,
    ) {
        $this->testMethodDetector = $testMethodDetector ?? new TestMethodDetector();
        $this->overrideMethodDetector = $overrideMethodDetector ?? new OverrideMethodDetector();
    }

    /**
     * @return class-string<\PhpParser\Node\Stmt\ClassMethod>
     */
    public function getNodeType(): string
    {
        return \PhpParser\Node\Stmt\ClassMethod::class;
    }

    /**
     * @param \PhpParser\Node\Stmt\ClassMethod $node
     * @return list<IdentifierRuleError>
     */
    public function processNode(\PhpParser\Node $node, Scope $scope): array
    {
        if (!$this->testClassScope->isRestrictedTestClass($scope)) {
            return [];
        }

        $methodName = $node->name->toString();

        if ($this->testMethodDetector->isTestMethod($node)) {
            return [];
        }

        if (str_starts_with($methodName, 'provider')) {
            return [];
        }

        if ($this->overrideMethodDetector->isOverride($node, $scope)) {
            return [];
        }

        $classReflection = $scope->getClassReflection();
        $className = $classReflection !== null ? $classReflection->getName() : '(unknown)';

        return [
            RuleErrorBuilder::message(
                sprintf(
                    'Move method %s() out of %s or make it a test, data provider, or framework override.',
                    $methodName,
                    $className
                )
            )
                ->identifier('customRules.testClassNonOverrideMethod')
                ->line($node->getStartLine())
            ->build(),
        ];
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\Shared;

/**
 * Detects PHPUnit test methods by name or #[Test] attribute.
 */
final class TestMethodDetector
{
    /**
     * Reports whether the class method is a test method.
     */
    public function isTestMethod(\PhpParser\Node\Stmt\ClassMethod $node): bool
    {
        if (str_starts_with($node->name->toString(), 'test')) {
            return true;
        }

        foreach ($node->attrGroups as $attrGroup) {
            foreach ($attrGroup->attrs as $attr) {
                $attrName = $attr->name->toString();
                if ($attrName === 'Test' || str_ends_with($attrName, '\\Test')) {
                    return true;
                }
            }
        }

        return false;
    }
}
<?php

declare(strict_types=1);

namespace Toolkit\PhpStan\Rule\TestClass;

use PHPStan\Rules\IdentifierRuleError;
use PHPStan\Rules\RuleErrorBuilder;

/**
 * Validates PHPUnit data provider naming conventions.
 */
final class ProviderNameValidator
{
    /**
     * @return list<IdentifierRuleError>
     */
    public function errors(string $methodName, int $line): array
    {
        $suffix = substr($methodName, 8);

        if ($suffix === '') {
            return [
                RuleErrorBuilder::message(
                    'Rename provider() to provider[TestCaseName], e.g. providerValidEmails().'
                )
                    ->identifier('customRules.providerNamingConvention')
                    ->line($line)
                    ->build(),
            ];
        }

        if (preg_match('/^[A-Z]$/', $suffix[0]) !== 1) {
            return [
                RuleErrorBuilder::message(
                    sprintf(
                        'Rename data provider %s() to use PascalCase after the "provider" prefix, e.g. providerValidEmails().',
                        $methodName
                    )
                )
                    ->identifier('customRules.providerNamingConvention')
                    ->line($line)
                    ->build(),
            ];
        }

        return [];
    }
}
