        for ($index = 0; $index < $count; $index++) {
            $token = $tokens[$index];
            if (!is_array($token) || $token[0] !== T_STRING || $token[1] !== $name) {
                continue;
            }
            $open = $this->skip($tokens, $index + 1);
            if (($tokens[$open] ?? null) !== '(') {
