    /**
     * Skips whitespace and comments.
     *
     * @param list<mixed> $tokens
     */
    public function skip(array $tokens, int $index): int
    {
        $count = count($tokens);
        while ($index < $count) {
            $token = $tokens[$index];
            if (!is_array($token) || !in_array($token[0], [T_WHITESPACE, T_COMMENT, T_DOC_COMMENT], true)) {
