    public function constant(string $name): mixed
    {
        return match (strtolower($name)) {
            'true' => true,
            'false' => false,
            'null' => null,
            default => null,
        };
    }

    /**
     * Uses a string or integer as an array key.
     *
     * @param mixed $value
     */
    public function key($value): string
    {
        if (is_string($value) || is_int($value)) {
            return (string) $value;
        }

        return '';
    }
