        $changes = [];
        foreach ($this->groups as $index => $rules) {
            $file = $inputs->get('file' . $index)->files[$rules[0]->file];
            try {
                $plan = $this->plan($file, $rules, $context->repair);
            } catch (RuntimeException|JsonException|NeonException $error) {
