final class ExtensionTest extends TestCase
{
    public function testRegisterExtensionCanAddPolicyToAnExistingCollectorAndCliReportsIt(): void
    {
        $project = new Project(['guard.yaml' => "version: 1\nstructure: {paths: [.], directories: []}\n"]);
        try {
            $registry = new Registry();
            (new \Guard\Extension\BuiltinExtension())->register($registry);
            $extension = new \Tests\Support\RequiredReadmeExtension();
            $extension->register($registry);
            $output = '';
            $app = new \Guard\Cli\Application($project->root, static function (string $text) use (&$output): void {
                $output .= $text;
            }, $registry);
            self::assertSame(1, $app->run(['check']));
            self::assertStringContainsString('[readme.required]', $output);
            $project->write('README.md', '# Project');
            self::assertSame(0, $app->run(['check']));
        } finally {
            $project->remove();
        }
    }

}


Policy/MetricLimitsTest.php
final class MetricLimitsTest extends TestCase
{
    /**
     * @throws JsonException

     * @throws \Nette\Neon\Exception
     */
    public function testEvaluateProfilesApplyToCollectedMetricsAfterSourceFilesAreRemoved(): void
    {
        $project = new Project(['src/A.php' => "<?php\n\n\n", 'src/Native.php' => "<?php\n\n\n", 'guard.yaml' => "version: 1\nmetrics:\n  source: [src]\n  profiles:\n    standard: {limits: {file: {lines: 1}}}\n    native: {extends: standard, limits: {file: {lines: 10}}}\n  default: standard\n  assignments: [{name: native, match: {paths: [src/Native.php]}, policy: native}]\n"]);
        try {
            $context = $project->context();
            $subject = (new \Guard\Collect\Php\PhpCollector())->collect($context)[0];
            unlink($project->root . '/src/A.php');
            unlink($project->root . '/src/Native.php');
            $plan = (new \Guard\Policy\MetricLimits())->evaluate($subject, $context);
            self::assertCount(1, $plan->findings);
            self::assertSame('src/A.php', $plan->findings[0]->path);
            self::assertSame('metrics.file_lines', $plan->findings[0]->rule);
            self::assertSame([], $plan->blockingFindings);
        } finally {
            $project->remove();
        }
    }
    public function testRejectsInformationOfAnotherType(): void
    {
        $this->expectException(PolicyException::class);
        (new \Guard\Policy\MetricLimits())->evaluate(new \Guard\Collect\Tree\DirectoryTree([]), new Context(new Configuration('/none', null, null, null, []), '/none/guard.yaml', false));
    }


    public function testViolationsAllowsMetricsEqualToTheConfiguredLimit(): void
    {
        $metrics = (new \Guard\Structure\Php\MetricParser())->parse("<?php\necho 1;\n", 'memory.php');
        self::assertSame([], (new \Guard\Policy\MetricLimits())->violations($metrics, \Guard\Config\Subject\LimitConfig::fromValues(['file.lines' => 2, 'file.ncloc' => 1])));
    }

}


