        $subject = new \Guard\Collect\Markdown\MarkdownDocuments([], ['skip.md'], [['pattern' => '*.md', 'paths' => ['README.md', 'extra.md', 'skip.md']], ['pattern' => '**/*.md', 'paths' => ['extra.md']]]);
