    {
        $project = new \Tests\Support\Project(['src/A.php' => '<?php $config->setRiskyAllowed(true);', 'src/Sub/B.php' => '<?php echo 1;', 'src/notes.md' => '# Notes', 'src/unread.txt' => 'metadata only', 'ignored/large.txt' => 'not selected']);
