<?php

declare(strict_types=1);

namespace Guard\Extension;

use Guard\Policy\PolicyException;
use ReflectionClass;
use RuntimeException;

/**
 * Loads explicitly configured, Composer-autoloadable extensions before collection.
 */
final class ExtensionLoader
{
    /**
     * Adds configured extensions after the registry's existing registrations.
     * @param array<string, array<string, mixed>> $extensions
     * @throws PolicyException when an extension cannot be constructed or registered
     */
    public function register(array $extensions, Registry $registry): void
    {
        foreach ($extensions as $class => $options) {
            try {
                $this->create($class, $options)->register($registry);
            } catch (RuntimeException $exception) {
                throw new PolicyException('Extension "' . $class . '": ' . $exception->getMessage(), 0, $exception);
            }
        }
    }

    /**
     * Uses the configuration factory, or a no-argument constructor for an optionless extension.
     * @param array<string, mixed> $options
     * @throws PolicyException when the class or options do not satisfy the extension contract
     */
    public function create(string $class, array $options): Extension
    {
        if (!class_exists($class)) {
            throw new PolicyException('Class "' . $class . '" was not found. Install it or add it to Composer autoload and run composer dump-autoload.');
        }
        if (!is_a($class, Extension::class, true)) {
            throw new PolicyException('Class "' . $class . '" must implement ' . Extension::class . '.');
        }
        $reflection = new ReflectionClass($class);
        if ($reflection->isAbstract()) {
            throw new PolicyException('Class "' . $class . '" is abstract. Configure a concrete extension class.');
        }
        if (is_a($class, ConfigurableExtension::class, true)) {
            return $class::fromOptions($options);
        }
        if ($options !== []) {
            throw new PolicyException('Options require ' . ConfigurableExtension::class . '. Implement fromOptions() or remove the options.');
        }
        $constructor = $reflection->getConstructor();
        if (!$reflection->isInstantiable() || ($constructor !== null && $constructor->getNumberOfRequiredParameters() > 0)) {
            throw new PolicyException('Class "' . $class . '" needs a public no-argument constructor or a ' . ConfigurableExtension::class . ' factory.');
        }
        return new $class();
    }
}
<?php

declare(strict_types=1);

namespace Guard\Extension;

/**
 * Creates an extension from the options declared under its class in guard.yaml.
 */
interface ConfigurableExtension extends Extension
{
    /**
     * Validates extension-owned options and returns a configured instance.
     * @param array<string, mixed> $options
     * @throws \Guard\Policy\PolicyException when options are invalid
     */
    public static function fromOptions(array $options): self;
}
<?php

declare(strict_types=1);

namespace Guard\Config\Reader;

use Guard\Policy\PolicyException;

/**
 * Validates extension declarations without loading or executing their classes.
 */
final class ExtensionConfigReader
{
    /**
     * Reads a class-name mapping whose values are extension-owned option mappings.
     * @return array<string, array<string, mixed>>
     * @throws PolicyException when class names or option mappings are malformed
     */
    public function read(mixed $value): array
    {
        if (!is_array($value)) {
            throw new PolicyException('guard.yaml.extensions must map extension class names to option mappings. Use {} for an extension without options.');
        }
        $extensions = [];
        foreach ($value as $class => $options) {
            if (!is_string($class) || $class === '' || trim($class) !== $class) {
                throw new PolicyException('guard.yaml.extensions must use non-empty extension class names as keys. Use a class-to-options mapping instead of a list.');
            }
            $extensions[$class] = $this->options($options, $class);
        }
        return $extensions;
    }

    /**
     * Leaves option semantics to the extension while requiring named options.
     * @return array<string, mixed>
     * @throws PolicyException when an extension's options are not a mapping
     */
    public function options(mixed $value, string $class): array
    {
        if (!is_array($value)) {
            throw new PolicyException('guard.yaml.extensions.' . $class . ' must be an option mapping. Use {} for no options.');
        }
        $options = [];
        foreach ($value as $key => $option) {
            if (!is_string($key) || $key === '') {
                throw new PolicyException('guard.yaml.extensions.' . $class . ' must use non-empty option names instead of a list.');
            }
            $options[$key] = $option;
        }
        return $options;
    }
}

